insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M1-A1-001', 'M1-A1-K2', 'numeric', 1, '正負の数の加法', '{"id": "T-M1-A1-001", "item": "M1-A1", "item_kind": "knowledge", "item_index": 2, "format": "numeric", "difficulty": 1, "title": "正負の数の加法", "variables": {"a": {"type": "int", "min": -9, "max": 9, "exclude": [0]}, "b": {"type": "int", "min": -9, "max": 9, "exclude": [0]}}, "constraints": ["a + b != 0"], "derived": {"ans": "a + b"}, "body": "次の計算をしなさい。\n{a} + ({b})\n", "answers": {"答え": "ans"}, "explanation": "同符号の2数の和は、絶対値の和に共通の符号を付けます。\n異符号の2数の和は、絶対値の差に絶対値の大きい方の符号を付けます。\n{a} + ({b}) = {ans}\n", "status": "draft"}'::jsonb, 'draft');
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-A2-001', 'M2-A2-K3', 'numeric', 2, '連立方程式（加減法）', '{"id": "T-M2-A2-001", "item": "M2-A2", "item_kind": "knowledge", "item_index": 3, "format": "numeric", "difficulty": 2, "title": "連立方程式（加減法）", "variables": {"x0": {"type": "int", "min": -5, "max": 5}, "y0": {"type": "int", "min": -5, "max": 5, "exclude": [0]}, "a1": {"type": "int", "min": 1, "max": 4}, "b1": {"type": "int", "min": 1, "max": 4}, "a2": {"type": "int", "min": 1, "max": 4}, "b2": {"type": "int", "min": -4, "max": -1}}, "constraints": ["a1 * b2 - a2 * b1 != 0", "x0 != y0"], "derived": {"c1": "a1 * x0 + b1 * y0", "c2": "a2 * x0 + b2 * y0"}, "body": "次の連立方程式を解きなさい。\n{a1}x + {b1}y = {c1}\n{a2}x + ({b2})y = {c2}\n", "answers": {"x": "x0", "y": "y0"}, "explanation": "加減法で文字を消去して解きます。\n2つの式を組み合わせて y（または x）を消去し、残った一次方程式を解くと\nx = {x0} が得られます。これを一方の式に代入すると y = {y0} となります。\n答え: x = {x0}, y = {y0}\n", "status": "draft"}'::jsonb, 'draft');
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-B2-001', 'M2-B2-K1', 'choice', 1, '三角形の合同条件（穴埋め選択）', '{"id": "T-M2-B2-001", "item": "M2-B2", "item_kind": "knowledge", "item_index": 1, "format": "choice", "difficulty": 1, "title": "三角形の合同条件（穴埋め選択）", "variables": {"q": {"type": "int", "min": 1, "max": 3}}, "constraints": [], "derived": {}, "case_var": "q", "body_by_case": {"1": "三角形の合同条件について、□にあてはまるものを選びなさい。\n「3組の□がそれぞれ等しいとき、2つの三角形は合同である。」\n", "2": "三角形の合同条件について、□にあてはまるものを選びなさい。\n「2組の辺とその□がそれぞれ等しいとき、2つの三角形は合同である。」\n", "3": "三角形の合同条件について、□にあてはまるものを選びなさい。\n「1組の辺とその□がそれぞれ等しいとき、2つの三角形は合同である。」\n"}, "correct_by_case": {"1": "辺", "2": "間の角", "3": "両端の角"}, "distractors_by_case": {"1": ["角", "間の角", "両端の角"], "2": ["両端の角", "対角", "辺"], "3": ["間の角", "対角", "辺"]}, "explanation": "三角形の合同条件は次の3つです。\n1. 3組の辺がそれぞれ等しい（三辺相等）\n2. 2組の辺とその間の角がそれぞれ等しい（二辺夾角相等）\n3. 1組の辺とその両端の角がそれぞれ等しい（一辺両端角相等）\n", "status": "draft"}'::jsonb, 'draft');
insert into templates (id, item_id, format, difficulty, title, spec, status) values ('T-M2-C1-001', 'M2-C1-K1', 'numeric', 1, '一次関数の変化の割合', '{"id": "T-M2-C1-001", "item": "M2-C1", "item_kind": "knowledge", "item_index": 1, "format": "numeric", "difficulty": 1, "title": "一次関数の変化の割合", "variables": {"m": {"type": "int", "min": -4, "max": 4, "exclude": [0]}, "n": {"type": "int", "min": -5, "max": 5}, "x1": {"type": "int", "min": -4, "max": 2}, "d": {"type": "int", "min": 1, "max": 5}}, "constraints": [], "derived": {"x2": "x1 + d", "y1": "m * x1 + n", "y2": "m * (x1 + d) + n"}, "body": "ある一次関数について、x = {x1} のとき y = {y1}、x = {x2} のとき y = {y2} です。\nこの一次関数の変化の割合を求めなさい。\n", "answers": {"変化の割合": "m"}, "explanation": "変化の割合 = (yの増加量) ÷ (xの増加量) です。\nyの増加量: {y2} - ({y1})\nxの増加量: {x2} - ({x1}) = {d}\nよって 変化の割合 = {m}\n", "status": "draft"}'::jsonb, 'draft');
